WITH filtered AS (SELECT *, LOWER(segment) AS segment_lower, COALESCE(segment, 'N/A') AS segment_filled FROM customers WHERE signup_date > TO_DATE('2023-09-06')) SELECT id, email, country, city, is_active, age, CORR(age, credit_limit) OVER (PARTITION BY country) AS corr_age_credit_limit, LAG(credit_limit, 1) OVER (ORDER BY age, id) AS prev_credit_limit, NTILE(5) OVER (PARTITION BY city ORDER BY credit_limit, id) AS credit_limit_bucket, CORR(credit_limit, age) OVER (PARTITION BY country, segment) AS corr_credit_limit_age FROM filtered;
